import {selectCompanion,COMPANION_STATS} from './campaign-companion.mjs';
import petMeta from '../assets/pets/pets-meta-v1.json' with {type:'json'};
import {PETS,PET_IDS,mirrorUnlocked,petRecord} from './campaign-pet-data.mjs';
export const petIcon=id=>{const r=petMeta.frames[PETS[id].row*6].rect,[w,h]=petMeta.size;return `background-image:url('assets/pets/${petMeta.file}');background-size:${w/r[2]*100}% ${h/r[3]*100}%;background-position:${r[0]/(w-r[2])*100}% ${r[1]/(h-r[3])*100}%;aspect-ratio:${r[2]}/${r[3]}`;};
export function artifactPanel(p){const open=mirrorUnlocked(p);return `<div class="mirror-layout"><section class="mirror-display"><i class="mirror-icon"></i><small>THE BEASTBINDING MIRROR</small><h3>收妖镜</h3><p>照见灵息 · 收伏妖兽</p></section><section class="mirror-description"><h3>${open?'收妖镜已获得':'通关第4关获得'}</h3><p>专用于宠物副本首领战后的野生灵宠。先用攻击降低它的生命，再在420距离内按 <kbd>V</kbd>，维持1.15秒镜光进行捕捉。</p><dl><dt>满血成功率</dt><dd>12%</dd><dt>低血上限</dt><dd>接近90%</dd><dt>再次使用</dt><dd>6秒</dd><dt>消耗品</dt><dd>无</dd></dl><p>捕捉失败可再次尝试；离开镜面范围会中断。击败灵宠后当次无法捕捉，成功后收入灵宠背包。</p><button data-mirror-equip ${open?'':'disabled'}>${p.mirrorEquipped?'已装备 · 点击卸下':'装备收妖镜'}</button><small>收妖镜占法器位，不提供攻击或防御加成。</small></section></div>`;}
export function petPanel(ui,p){const pets=petRecord(p),selected=pets.find(v=>v.id===ui.petSelected)||pets.find(v=>v.id===p.activePetId)||pets[0],d=selected&&PETS[selected.kind];return `<div class="pet-archive"><section><div class="section-title"><h3>灵宠背包</h3><small>已收伏 ${pets.length} 只 · 最多一只出战</small></div><div class="pet-bag-grid">${pets.map(v=>`<button class="pet-owned ${v.id===selected?.id?'selected':''}" data-pet-select="${v.id}" aria-label="查看${PETS[v.kind].name}"><i style="${petIcon(v.kind)}"></i>${p.activePetId===v.id?'<em class="pet-active-badge">出战中</em>':''}<strong>${PETS[v.kind].name}</strong><small>形态 ${v.form+1} · ${PETS[v.kind].forms[v.form]}</small></button>`).join('')||'<div class="pet-empty"><h3>尚未收伏灵宠</h3><p>通关第5、7、9关后，在关卡详情进入宠物副本。击败首领后，新的灵兽会出现。</p><p>装备收妖镜，降低灵宠生命后按 V 捕捉。</p></div>'}</div><div class="pet-places">${PET_IDS.map(id=>`<div><i style="${petIcon(id)}"></i><span>第${PETS[id].stage}关 · ${PETS[id].name}<small>通关本关后解锁专属副本</small></span></div>`).join('')}</div></section><aside class="pet-description">${d?`<i class="pet-portrait" style="${petIcon(d.id)}"></i><h3>${d.name}</h3><button class="pet-deploy-button" data-pet-deploy="${selected.id}" ${ui.getWorld()?'disabled':''}>${p.activePetId===selected.id?'取消出战':'设为出战灵宠'}</button><p class="pet-deploy-note">${ui.getWorld()?'返回世界地图后可调整出战。':p.activePetId===selected.id?'下一次进入关卡时，它会自动出现在身边。':'选择一只已捕获灵宠，陪同下一次关卡。'}</p><p>${d.description}</p><dl><dt>当前形态</dt><dd>${d.forms[selected.form]}</dd><dt>捕捉地点</dt><dd>第${selected.capturedStage}关 · 宠物副本</dd><dt>伴战方式</dt><dd>${COMPANION_STATS[d.id].ranged?'灵弹支援':'近身扑爪'}</dd></dl><div class="pet-form-line">${d.forms.map((n,i)=>`<span class="${i===selected.form?'active':''}"><b>0${i+1}</b>${n}</span>`).join('')}</div><p class="system-note">出战后自动跟随、跳上台面并协助攻击；灵宠受伤倒下后本关退场，下次进入关卡恢复。捕捉阶段自动停手。进化与养成后续开放。</p>`:'<i class="mirror-icon"></i><h3>循灵而行</h3><p>选择已捕获的灵宠，查看它的来历与形态。</p>'}</aside></div>`;}
export function handlePetUI(ui,b){if(b.dataset.petDeploy){ui.mutate(()=>{if(ui.getWorld())throw Error('请在世界地图调整出战灵宠');const p=ui.getProfile();return selectCompanion(p,p.activePetId===b.dataset.petDeploy?null:b.dataset.petDeploy);});return true;}if(b.dataset.petSelect){ui.petSelected=b.dataset.petSelect;ui.render();return true;}if(b.hasAttribute('data-mirror-equip')){ui.mutate(()=>{const p=ui.getProfile();if(!mirrorUnlocked(p))throw Error('通关第4关后获得收妖镜');p.mirrorEquipped=!p.mirrorEquipped;return p.mirrorEquipped?'已装备收妖镜 · 宠物副本中按 V 使用':'已卸下收妖镜';});return true;}return false;}
